.btn {
    padding: 10px 20px;
    border-radius: 6px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    border: none;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.btn-primary {
    background: var(--primary);
    color: white;
}

.btn-primary:hover {
    background: #0052cc;
}

.btn-secondary {
    background: transparent;
    color: var(--text-body);
    border: 1px solid var(--border);
}

.btn-secondary:hover {
    background: var(--bg-page);
}

/* Hero Section */
.hero {
    padding: 140px 24px 100px;
    text-align: center;
    background: linear-gradient(180deg, #ffffff 0%, #f7f7f7 100%);
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 14px;
    background: var(--primary-light);
    color: var(--primary);
    font-size: 13px;
    border-radius: 20px;
    margin-bottom: 24px;
}

.hero-badge::before {
    content: '';
    width: 8px;
    height: 8px;
    background: var(--success);
    border-radius: 50%;
}

.hero h1 {
    font-size: 56px;
    font-weight: 700;
    color: var(--text-title);
    margin-bottom: 20px;
    line-height: 1.2;
}

.hero h1 span {
    color: var(--primary);
}

.hero-subtitle {
    font-size: 20px;
    color: var(--text-secondary);
    max-width: 700px;
    margin: 0 auto 40px;
    line-height: 1.7;
}

.hero-cta {
    display: flex;
    gap: 16px;
    justify-content: center;
    margin-bottom: 60px;
}

.hero-cta .btn {
    padding: 14px 32px;
    font-size: 16px;
}

.hero-stats {
    display: flex;
    justify-content: center;
    gap: 60px;
    padding-top: 40px;
    border-top: 1px solid var(--border);
}

.stat {
    text-align: center;
}

.stat-value {
    font-size: 36px;
    font-weight: 700;
    color: var(--text-title);
}

.stat-label {
    font-size: 14px;
    color: var(--text-secondary);
    margin-top: 4px;
}

/* Features Section */
.features {
    padding: 100px 24px;
    max-width: 1200px;
    margin: 0 auto;
}

.section-header {
    text-align: center;
    margin-bottom: 60px;
}

.section-header h2 {
    font-size: 40px;
    font-weight: 600;
    color: var(--text-title);
    margin-bottom: 16px;
}

.section-header p {
    font-size: 18px;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
}

.feature-card {

