.case-card {
    background: var(--bg-page);
    border-radius: 12px;
    padding: 32px 24px;
    text-align: center;
    transition: all 0.3s;
}

.case-card:hover {
    background: var(--primary);
    color: white;
    transform: translateY(-4px);
}

.case-card:hover h4,
.case-card:hover p {
    color: white;
}

.case-icon {
    font-size: 40px;
    margin-bottom: 16px;
}

.case-card h4 {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-title);
    margin-bottom: 8px;
    transition: color 0.3s;
}

.case-card p {
    font-size: 14px;
    color: var(--text-secondary);
    transition: color 0.3s;
}

/* Pricing */
.pricing {
    padding: 100px 24px;
    max-width: 1200px;
    margin: 0 auto;
}

.pricing-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    margin-top: 40px;
}

.pricing-card {
    background: var(--bg-white);
    border-radius: 16px;
    padding: 40px 32px;
    border: 1px solid var(--border);
    position: relative;
}

.pricing-card.popular {
    border-color: var(--primary);
    box-shadow: 0 20px 40px rgba(0, 110, 255, 0.1);
}

.popular-badge {
    position: absolute;
    top: -12px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--primary);
    color: white;
    padding: 6px 16px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
}

.pricing-card h3 {
    font-size: 20px;
    font-weight: 600;
    color: var(--text-title);
    margin-bottom: 8px;
}

.pricing-desc {
    font-size: 14px;
    color: var(--text-secondary);
    margin-bottom: 24px;
}

.pricing-price {
    margin-bottom: 32px;
}

.pricing-price .currency {
    font-size: 24px;
    font-weight: 600;
    color: var(--text-title);
}

.pricing-price .amount {
    font-size: 48px;
    font-weight: 700;
    color: var(--text-title);
}

.pricing-price .period {
    font-size: 14px;
    color: var(--text-secondary);
}

.pricing-features {
    list-style: none;
    margin-bottom: 32px;
}

.pricing-features li {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
    font-size: 14px;
    color: var(--text-body);
}

.pricing-features li::before {
    content: '✓';
    color: var(--success);
    font-weight: 600;
}

.pricing-card .btn {
    width: 100%;
    justify-content: center;
}

/* FAQ */
.faq {
    padding: 100px 24px;
    background: var(--bg-white);
}

.faq-content {
    max-width: 800px;
    margin: 0 auto;
}

.faq-list {
    margin-top: 40px;
}

.faq-item {
    border-bottom: 1px solid var(--border);
    padding: 24px 0;
}

.faq-question {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-title);
    margin-bottom: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
}

.faq-answer {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.7;
    padding-right: 40px;
}

/* CTA Section */
.cta {
    padding: 100px 24px;
    text-align: center;
    background: linear-gradient(135deg, var(--primary) 0%, #0052cc 100%);
    color: white;
}

.cta h2 {
    font-size: 40px;
    font-weight: 600;
    margin-bottom: 16px;
}

.cta p {
    font-size: 18px;
    opacity: 0.9;
    margin-bottom: 32px;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.cta .btn {
    padding: 14px 32px;

